#AD163713066910.ad-template .col .ad-view { position:relative; } window.googletag = window.googletag || {cmd: []}; googletag.cmd.push(function() { googletag.defineSlot('/21724694934/21835161981/22652325777', [[580, 400], [640, 360]], 'aiin-adincontent-middle').addService(googletag.pubads()).setTargeting('TARGET_INV_ZONE', ['content']).setTargeting('TARGET_CREATIVE', ['ADEXCHANGE_CPM']); googletag.enableServices(); googletag.display('aiin-adincontent-middle'); googletag.pubads().addEventListener('slotRenderEnded', function (event) { if (event.isEmpty == true && event.slot.getSlotId().getName() == '/21724694934/21835161981/22652325777') { var adIns = document.createElement('ins'); adIns.className = "adsbyaiinad"; adIns.setAttribute('data-aiinad-inv', "22652325837"); document.getElementById('aiin-adincontent-middle').append(adIns); } }); }); 이철우 예비후보는 이날 보도자료를 통해 "김 후보가 저와 관련된 수사 사건을 두고 비방과 흑색선전, 인신공격성 발언을 이어가고 있다"며 "분노와 안타까움을 금할 수 없다"고 밝혔다. 이철우 예비후보는 김 후보가 경찰 보완수사 과정에서 새로운 혐의가 추가된 것처럼 주장했으나 이는 사실과 다르다고 반박했다. 그는 "경찰 수사는 처음부터 지금까지 혐의 적용에 변화가 없다"며 "오히려 검찰이 두 차례에 걸쳐 보완수사를 요청한 것은 경찰 수사가 충실하지 못했고 사실관계와 법리 검토가 충분하지 않았음을 보여주는 것"이라고 설명했다. 이어 "3년 가까이 압수수색과 소환조사, 관련자 조사까지 이어졌음에도 결정적인 증거를 확보하지 못했기 때문에 검찰이 거듭 보완수사를 요구한 것"이라며 "김 후보는 이를 마치 저에게 불리한 새로운 상황이 발생한 것처럼 왜곡하여 정치적으로 활용하고 있다"고 비판했다. 이철우 예비후보는 김 후보가 "기소는 시간문제"라거나 "재판 결과에 따라 보궐선거 가능성이 있다"는 식의 발언에 대해서도 "검찰 수사와 재판 절차를 무시한 무책임한 정치 선동"이라고 규정했다. 그는 "경찰이 사건을 송치했다고 해서 기소가 되는 것이 아니다"라며 "검찰이 두 차례나 보완수사를 요구한 이유도 애초에 이 사건이 범죄로 성립할 수 있는지 여부 자체를 엄격하게 보고 있기 때문"이라고 강조했다. 특히 이철우 예비후보는 김 후보의 과거 발언을 환기하며 "김 후보는 2019년 12월 정책위의장 정견 발표를 하면서 '적폐청산' 수사를 받을 당시 극심한 고통 속에서 극단적 선택까지 생각할 정도였다고 스스로 밝히며 '당이 어려울 때 서로 힘이 되어주자'고 이야기한 바 있다"며 "그때의 김재원과 지금의 김재원은 다른 사람입니까"라고 되물었다. 이철우 예비후보는 정권 교체 이후 서울, 강원, 경남, 인천, 충북도 등 국민의힘 소속 시·도지사들이 정치적 수사에 시달리고 있다며 "같은 당의 동지가 정치적 의도가 의심되는 수사와 음해성 보도에 시달릴 때, 최소한 신중한 태도를 보이거나 함께 부당함에 맞서는 것이 도리"라고 했다. 아울러 국민의힘 공천관리위원회가 전날 '당내 경선 네거티브 금지' 공문을 발송하고 위원회 차원의 강력한 경고 조치를 공언했음에도 김 후보가 공문을 받은 당일 경북도당에서 기자회견을 열어 또다시 비방과 흑색선전에 나섰다고 지적했다. 이철우 예비후보는 "심지어 오늘 아침 최고위원회의에서까지 공개 발언을 통해 저를 비방하는 행동을 벌였다"며 "최고위원직을 사퇴하지 않고 선거에 뛰면서, 최고위에서 지방선거와 관련된 일체의 발언과 행위를 하지 않겠다고 약속했던 김 후보가 약속을 깨고 심판과 선수를 병행하며 최고위원직을 악용했다"고 비판했다. 이철우 예비후보는 "경북은 단순히 한 지역의 선거구가 아니다"라며 "대구·경북은 대한민국 보수정치의 뿌리이자 자유민주주의와 시장경제, 국가 정체성을 지켜온 마지막 보루"라고 강조했다. 그러면서 "중앙당은 당내 경선을 진흙탕으로 만들고 보수 전체의 명예를 훼손하는 네거티브와 허위·왜곡 공세를 더 이상 좌시해서는 안 된다"며 "당의 이름으로 단호하게 경고하고, 공정한 경선 질서를 반드시 바로 세워야 한다"고 촉구했다. 정재은 기자 jaeeun@gokorea.kr 다른기사 저작권자 © 공감신문 무단전재 및 재배포 금지 /**************************************************
